using Microsoft.AspNetCore.DataProtection;
using Shop.Modules.Credit;
using Shop.Modules.Notifications;
using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;

public sealed class CreditReminderTests
{
    private const string V="AAAAAAAAAAE=",H="AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
    [Theory][InlineData("CreditApproved","Received",true)][InlineData("Fulfilled","Deposited",true)][InlineData("CreditApproved","BouncedReported",true)][InlineData("Fulfilled","Withdrawn",true)][InlineData("AwaitingPayment","Received",false)][InlineData("Cancelled","Received",false)][InlineData("Expired","Deposited",false)][InlineData("Paid","Received",false)][InlineData("CreditApproved","CollectedReported",false)][InlineData("Fulfilled","ReturnedToCustomer",false)]
    public void ReminderOnlyInformsCommittedCreditOrdersWithHeldInstruments(string order,string state,bool expected)=>Assert.Equal(expected,CreditReminderRules.Eligible(order,state));
    [Fact]public void ConfirmationExactVersionsAndPrivateNoteAreRequired(){var body=new CreditReminderInput(V,V,H,"Private staff review only",true);CreditReminderRules.Validate(body);Assert.Throws<BusinessException>(()=>CreditReminderRules.Validate(body with{Confirmed=false}));Assert.Throws<BusinessException>(()=>CreditReminderRules.Validate(body with{Note=""}));Assert.Throws<BusinessException>(()=>CreditReminderRules.Validate(body with{LedgerVersion="bad"}));Assert.Throws<BusinessException>(()=>CreditReminderRules.Validate(body with{PreviewFingerprint="bad"}));}
    private static CreditReminderNotificationEvent Notice()=>new(new string('a',32),"QA_OWNER",new string('b',32),new string('c',32),"2027-01-01","9007199254740993","2026-10-28",DateTimeOffset.Parse("2026-10-27T20:30:00Z"));
    [Fact]public void InboxBoundaryRequiresCanonicalPositiveRialAndTheActualTehranCivilDay(){var n=Notice();CreditInboxRules.Validate(n);foreach(var wrong in new[]{n with{AmountRial="0"},n with{AmountRial="09007199254740993"},n with{AmountRial="9223372036854775808"},n with{CivilDay="2026-10-27"},n with{DueDate="2027-02-30"},n with{OwnerId="qa_owner"}})Assert.Throws<BusinessException>(()=>CreditInboxRules.Validate(wrong));}
    [Fact]public void ReminderAndInboxProtectionAreBoundToOwnerOrderIdAndPurpose(){var provider=new EphemeralDataProtectionProvider();var p=new DataProtectionCreditReminderProtection(provider);var owner=Guid.NewGuid().ToString();var order=new string('a',32);var id=new string('b',32);var bytes=p.Protect("event",owner,order,id,"synthetic only");Assert.Equal("synthetic only",p.Unprotect("event",owner.ToUpperInvariant(),order,id,bytes));Assert.Throws<BusinessException>(()=>p.Unprotect("receipt",owner,order,id,bytes));Assert.Throws<BusinessException>(()=>p.Unprotect("event",Guid.NewGuid().ToString(),order,id,bytes));Assert.Throws<BusinessException>(()=>p.Unprotect("event",owner,new string('c',32),id,bytes));var inbox=new DataProtectionCreditInboxProtection(provider);var payload=inbox.Protect(owner,id,"synthetic only");Assert.Equal("synthetic only",inbox.Unprotect(owner,id,payload));Assert.Throws<BusinessException>(()=>inbox.Unprotect(owner,new string('c',32),payload));Assert.Throws<BusinessException>(()=>inbox.Unprotect(Guid.NewGuid().ToString(),id,payload));}
    [Fact]public void UnsetReminderFieldsRemainExplicitNullInApiJson(){var c=new ChequeSummary(new string('a',32),"CH-"+new string('A',32),new string('b',32),new string('c',32),1,"2027-01-01","10","Received",V,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow);var p=new CreditReminderPage(1,c.OrderId,V,"CreditApproved",c,"2026-10-28",H,null,false,null);var raw=System.Text.Json.JsonSerializer.Serialize(p,new System.Text.Json.JsonSerializerOptions(System.Text.Json.JsonSerializerDefaults.Web){DefaultIgnoreCondition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull});Assert.Contains("\"sentToday\":null",raw);Assert.Contains("\"nextSequence\":null",raw);Assert.Contains("\"bankVerified\":false",raw);}
}
